def validate_ledger(
    ledger: dict[str, Any],
    *,
    formal_dir: Path = FORMAL_DIR,
    verus_source_dir: Path = VERUS_SOURCE_DIR,
    release: bool = False,
    evidence: dict[str, Any] | None = None,
    verus_evidence: dict[str, Any] | None = None,
    cross_tool_evidence: dict[str, Any] | None = None,
    evidence_root: Path = ROOT_DIR,
    expected_verus_source_manifest_sha256: str | None = None,
    verus_log_path: Path | None = None,
    check_retired_paths: bool = True,
) -> LedgerValidation:
    """Validate schema, source linkage, trust boundaries, and release evidence."""

    errors: list[str] = []
    expected_ledger_keys = {
        "schema_version",
        "protocol",
        "status_values",
        "machine_checked_completion",
        "obligations",
    }
    if set(ledger) != expected_ledger_keys:
        errors.append(
            "proof ledger fields must equal "
            f"{sorted(expected_ledger_keys)}, found {sorted(ledger)}; "
            "tool runs and counts belong only in generated proof evidence"
        )
    if ledger.get("schema_version") != LEDGER_SCHEMA_VERSION:
        errors.append(
            f"proof ledger schema_version must equal {LEDGER_SCHEMA_VERSION}"
        )
    if ledger.get("protocol") != "sumeragi-v2":
        errors.append("proof ledger protocol must equal sumeragi-v2")
    if ledger.get("status_values") != list(STATUS_VALUES):
        errors.append(f"proof ledger status_values must equal {list(STATUS_VALUES)}")
    completion = ledger.get("machine_checked_completion")
    if not isinstance(completion, bool):
        errors.append("machine_checked_completion must be a boolean")
        completion = False

    module_sources, module_errors = _module_sources(formal_dir)
    errors.extend(module_errors)
    errors.extend(_resume_vote_witness_errors(formal_dir))
    errors.extend(_retired_liveness_errors(formal_dir))
    errors.extend(_bounded_view_dependency_errors(formal_dir))
    errors.extend(_reachable_oracle_guard_errors(formal_dir))
    errors.extend(_generalized_context_init_errors(formal_dir))
    errors.extend(_safety_property_source_fidelity_errors(formal_dir))
    errors.extend(_historical_timeout_derivation_errors(formal_dir))
    errors.extend(_async_spec_shape_errors(formal_dir))
    errors.extend(_async_proof_architecture_errors(formal_dir))
    errors.extend(_application_completion_source_fidelity_errors(formal_dir))
    errors.extend(_progress_witness_source_fidelity_errors(formal_dir))
    errors.extend(_effective_lock_acquisition_source_fidelity_errors(formal_dir))
    errors.extend(_causal_fifo_rank_mutation_source_fidelity_errors(formal_dir))
    errors.extend(_causal_fifo_rank_mutation_runner_errors(ROOT_DIR))
    errors.extend(
        _deferred_handoff_mutation_source_fidelity_errors(formal_dir, ROOT_DIR)
    )
    errors.extend(
        _reply_writer_deadline_formal_source_fidelity_errors(
            formal_dir, ROOT_DIR
        )
    )
    errors.extend(
        _typed_rollover_handoff_formal_source_fidelity_errors(
            formal_dir, ROOT_DIR
        )
    )
    errors.extend(
        _reply_route_ownership_source_fidelity_errors(formal_dir, ROOT_DIR)
    )
    errors.extend(_effective_lock_acquisition_mutation_runner_errors(ROOT_DIR))
    errors.extend(
        _effect_capacity_mutation_source_fidelity_errors(formal_dir, ROOT_DIR)
    )
    errors.extend(
        _post_decision_timeout_mutation_source_fidelity_errors(
            formal_dir, ROOT_DIR
        )
    )
    errors.extend(
        _certified_response_registration_mutation_source_fidelity_errors(
            formal_dir, ROOT_DIR
        )
    )
    errors.extend(
        _decision_recovery_lifecycle_mutation_source_fidelity_errors(
            formal_dir, ROOT_DIR
        )
    )
    errors.extend(_same_round_semantic_kernel_source_fidelity_errors(ROOT_DIR))
    errors.extend(_installed_tc_selector_source_fidelity_errors(formal_dir))
    errors.extend(_local_proposal_timeout_source_fidelity_errors(ROOT_DIR))
    errors.extend(_proposal_timeout_exactness_source_fidelity_errors(ROOT_DIR))
    errors.extend(
        _locked_assembly_retention_mutation_errors(formal_dir, ROOT_DIR)
    )
    errors.extend(
        _locked_body_reproposal_source_fidelity_errors(formal_dir, ROOT_DIR)
    )
    errors.extend(
        _locked_body_reproposal_mutation_runner_errors(formal_dir, ROOT_DIR)
    )
    errors.extend(_async_source_fidelity_errors(formal_dir))
    errors.extend(
        _local_runner_service_contract_source_fidelity_errors(
            ledger,
            repo_root=ROOT_DIR,
            formal_dir=formal_dir,
        )
    )
    errors.extend(_async_historical_recovery_source_fidelity_errors(formal_dir))
    errors.extend(_ownership_n1_configuration_errors(formal_dir))
    errors.extend(
        _merge_runtime_config_production_source_fidelity_errors(ROOT_DIR)
    )
    errors.extend(
        _transport_hardening_production_source_fidelity_errors(ROOT_DIR)
    )
    errors.extend(
        _reply_writer_deadline_production_source_fidelity_errors(ROOT_DIR)
    )
    errors.extend(
        _queue_plan_semantic_request_production_source_fidelity_errors(ROOT_DIR)
    )
    errors.extend(_exact_output_production_source_fidelity_errors(ROOT_DIR))
    errors.extend(
        _kura_application_receipt_production_source_fidelity_errors(ROOT_DIR)
    )
    errors.extend(
        _kura_retirement_progress_production_source_fidelity_errors(ROOT_DIR)
    )
    errors.extend(
        _kura_native_amx_standalone_evidence_production_source_fidelity_errors(
            ROOT_DIR
        )
    )
    errors.extend(_chain_source_fidelity_errors(formal_dir))
    errors.extend(
        _successor_stale_token_mutation_source_fidelity_errors(formal_dir)
    )
    errors.extend(_replay_trace_source_fidelity_errors(ROOT_DIR))
    errors.extend(_nightly_chaos_cold_cache_errors(ROOT_DIR))
    errors.extend(_production_liveness_release_inventory_errors(ROOT_DIR))
    for cfg_name in REQUIRED_TLC_CONFIGS:
        cfg = formal_dir / cfg_name
        if not cfg.is_file():
            errors.append(f"missing required TLC counterexample configuration: {cfg}")
            continue
        expected_header = REQUIRED_TLC_CONFIG_HEADERS[cfg_name]
        source = cfg.read_text(encoding="utf-8")
        if not source.startswith(expected_header + "\n"):
            errors.append(
                f"{cfg}: TLC configuration must start with {expected_header!r}"
            )
        if (
            cfg_name != "effective_lock_acquisition.cfg"
            and '  ValidSubjects = {"A"}\n' not in source
        ):
            errors.append(
                f"{cfg}: TLC configuration must keep B externally invalid so "
                "bounded searches exercise validation rejection"
            )
        if (
            cfg_name == "effective_lock_acquisition.cfg"
            and "AcquisitionSubjects = "
            "{AcquisitionSubjectA, AcquisitionSubjectB}\n" not in source
        ):
            errors.append(
                f"{cfg}: effective-lock search must keep two distinct subjects"
            )

    obligations = ledger.get("obligations")
    if not isinstance(obligations, list) or not obligations:
        errors.append("proof ledger obligations must be a non-empty array")
        obligations = []
    errors.extend(_machine_checked_completion_contract_errors())
    errors.extend(_proof_obligation_inventory_errors(obligations))
    errors.extend(_cross_tool_contract_errors())
    errors.extend(_proof_obligation_architecture_errors(obligations, module_sources))
    errors.extend(_proof_status_dependency_errors(obligations))
    errors.extend(_proofless_release_theorem_errors(obligations, module_sources))
    specified_unproved = [
        obligation.get("id", f"obligations[{index}]")
        if _nonempty_string(obligation.get("id"))
        else f"obligations[{index}]"
        for index, obligation in enumerate(obligations)
        if isinstance(obligation, dict)
        and obligation.get("status") == "specified_unproved"
        and obligation.get("id") in _MACHINE_CHECKED_COMPLETION_TARGET_ID_SET
    ]
    if completion and specified_unproved:
        errors.append(
            "machine_checked_completion=true rejects specified_unproved "
            f"target obligations: {specified_unproved}"
        )
    if completion:
        errors.extend(_machine_checked_completion_status_errors(obligations))
    seen_ids: set[str] = set()
    for index, obligation in enumerate(obligations):
        where = f"obligations[{index}]"
        if not isinstance(obligation, dict):
            errors.append(f"{where} must be an object")
            continue
        obligation_id = obligation.get("id")
        requirement = obligation.get("requirement")
        module = obligation.get("module")
        symbol = obligation.get("symbol")
        status = obligation.get("status")
        for field_name, value in (
            ("id", obligation_id),
            ("requirement", requirement),
            ("module", module),
            ("symbol", symbol),
        ):
            if not _nonempty_string(value):
                errors.append(f"{where}.{field_name} must be a non-empty string")
        if not _nonempty_string(obligation_id):
            continue
        if obligation_id in seen_ids:
            errors.append(f"duplicate proof obligation id: {obligation_id}")
        seen_ids.add(obligation_id)
        if status not in STATUS_VALUES:
            errors.append(f"{where}.status has unknown value: {status!r}")
            continue
        if not _nonempty_string(module) or not _nonempty_string(symbol):
            continue
        cross_tool_contract = CROSS_TOOL_REFINEMENT_BY_ID.get(obligation_id)
        if status == "cross_tool_proved" and cross_tool_contract is None:
            errors.append(
                f"{where} uses cross_tool_proved outside the reviewed production "
                "refinement inventory"
            )
            continue
        if status == "tlaps_proved" and cross_tool_contract is not None:
            errors.append(
                f"{where} is a production refinement seam and cannot be "
                "promoted with TLAPS evidence alone"
            )
        if status in {
            "tlaps_proved",
            "cross_tool_proved",
            "specified_unproved",
        }:
            if (
                status == "tlaps_proved"
                and module not in RELEASE_PROOF_MODULES
                and module != ASYNC_LIVENESS_FACADE
            ):
                errors.append(
                    f"{where} claims TLAPS proof in non-release module {module}"
                )
            source = module_sources.get(module)
            if source is None:
                module_path = formal_dir / f"{module}.tla"
                if module_path.is_file():
                    source = module_path.read_text(encoding="utf-8")
                    errors.extend(tla_shortcut_errors(module_path, source))
                else:
                    errors.append(f"{where} references missing module {module}")
                    continue
            names = _symbol_names(symbol)
            if not names:
                errors.append(f"{where}.symbol contains no symbols")
            for name in names:
                if not re.fullmatch(r"[A-Za-z_][A-Za-z0-9_]*", name):
                    errors.append(f"{where}.symbol is not a TLA+ identifier: {name}")
                elif not _symbol_exists(
                    source, name, theorem_only=status == "tlaps_proved"
                ):
                    declaration = "theorem" if status == "tlaps_proved" else "symbol"
                    errors.append(
                        f"{where} references missing {declaration} {module}!{name}"
                    )
        elif module != "trusted-boundary":
            errors.append(
                f"{where} with status {status} must use module trusted-boundary"
            )

    if verus_source_dir.is_dir():
        for path in sorted(verus_source_dir.rglob("*.rs")):
            errors.extend(verus_shortcut_errors(path, path.read_text(encoding="utf-8")))
    else:
        errors.append(f"missing Verus production proof source directory: {verus_source_dir}")

    if check_retired_paths:
        for path in RETIRED_PATHS:
            if _retired_path_present(path):
                errors.append(f"retired Sumeragi v1 formal corridor still exists: {path}")

    if release:
        errors.extend(
            _release_evidence_errors(
                ledger,
                evidence,
                formal_dir=formal_dir,
                root_dir=evidence_root,
            )
        )
        errors.extend(
            _cross_tool_evidence_errors(
                ledger,
                cross_tool_evidence,
                tlaps_evidence=evidence,
                verus_evidence=verus_evidence,
                formal_dir=formal_dir,
                root_dir=evidence_root,
                expected_verus_source_manifest_sha256=(
                    expected_verus_source_manifest_sha256
                ),
                verus_log_path=verus_log_path,
            )
        )

    return LedgerValidation(tuple(errors), bool(completion))


def _parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(description=__doc__)
    mode = parser.add_mutually_exclusive_group()
    mode.add_argument(
        "--release",
        action="store_true",
        help="fail unless every deductive obligation has backend proof evidence",
    )
    parser.add_argument(
        "--ledger",
        type=Path,
        default=LEDGER_PATH,
        help="proof ledger path (primarily for tests and release tooling)",
    )
    parser.add_argument(
        "--evidence",
        type=Path,
        help="fresh proof evidence generated by the pinned TLAPS runner",
    )
    parser.add_argument(
        "--verus-evidence",
        type=Path,
        help="fresh source-bound Verus evidence linked by cross-tool proofs",
    )
    parser.add_argument(
        "--verus-log",
        type=Path,
        help=(
            "archived Verus transcript to validate instead of the canonical "
            "target path"
        ),
    )
    parser.add_argument(
        "--cross-tool-evidence",
        type=Path,
        help="canonical 4+7+6 production-refinement evidence",
    )
    mode.add_argument(
        "--write-evidence",
        type=Path,
        help="write canonical source- and log-bound TLAPS evidence and exit",
    )
    mode.add_argument(
        "--write-cross-tool-evidence",
        type=Path,
        help=(
            "write canonical cross-tool evidence from --ledger, --evidence, "
            "and --verus-evidence, then exit"
        ),
    )
    parser.add_argument(
        "--tlapm-version",
        help="full pinned TLAPM version string used with --write-evidence",
    )
    parser.add_argument(
        "--tlaps-log-dir",
        type=Path,
        help="directory containing strict-run logs used with --write-evidence",
    )
    mode.add_argument(
        "--print-proof-modules",
        action="store_true",
        help="print the ordered deductive module list and exit",
    )
    mode.add_argument(
        "--print-source-manifest-sha256",
        action="store_true",
        help="print the current canonical TLA+ source-manifest digest and exit",
    )
    mode.add_argument(
        "--print-cross-tool-obligations",
        action="store_true",
        help=(
            "print cross_tool_proved obligation IDs in canonical order; empty "
            "output means no cross-tool evidence document is required"
        ),
    )
    mode.add_argument(
        "--check-production-causal-fifo",
        action="store_true",
        help=(
            "check only the source-bound production persisted-continuation/"
            "causal-FIFO seam and exit"
        ),
    )
    return parser


def main(argv: Sequence[str] | None = None) -> int:
    args = _parser().parse_args(argv)
    if args.print_proof_modules:
        print("\n".join(RELEASE_PROOF_MODULES))
        return 0
    if args.print_source_manifest_sha256:
        print(_formal_source_manifest()["sha256"])
        return 0
    if args.print_cross_tool_obligations:
        try:
            ledger = load_ledger(args.ledger)
        except (OSError, json.JSONDecodeError, DuplicateKeyError) as error:
            print(f"proof ledger load failed: {error}", file=sys.stderr)
            return 1
        if not isinstance(ledger, dict):
            print("proof ledger must be a JSON object", file=sys.stderr)
            return 1
        obligations = ledger.get("obligations")
        if not isinstance(obligations, list):
            print("proof ledger obligations must be an array", file=sys.stderr)
            return 1
        cross_ids = [
            obligation.get("id")
            for obligation in obligations
            if isinstance(obligation, dict)
            and obligation.get("status") == "cross_tool_proved"
        ]
        unknown = [
            obligation_id
            for obligation_id in cross_ids
            if obligation_id not in CROSS_TOOL_REFINEMENT_BY_ID
        ]
        if unknown:
            print(
                "unreviewed cross_tool_proved obligations: " + repr(unknown),
                file=sys.stderr,
            )
            return 1
        expected = [
            contract.obligation_id
            for contract in CROSS_TOOL_REFINEMENT_CONTRACTS
            if contract.obligation_id in cross_ids
        ]
        if cross_ids != expected:
            print(
                "cross_tool_proved obligations are not in canonical order",
                file=sys.stderr,
            )
            return 1
        print("\n".join(expected))
        return 0
    if args.check_production_causal_fifo:
        errors = _production_causal_fifo_source_fidelity_errors()
        if errors:
            for error in errors:
                print(f"error: {error}", file=sys.stderr)
            return 1
        print("production persisted-continuation/causal-FIFO seam is source-bound")
        return 0
    if args.write_evidence is not None:
        if any(
            value is not None
            for value in (
                args.evidence,
                args.verus_evidence,
                args.verus_log,
                args.cross_tool_evidence,
            )
        ):
            print(
                "--write-evidence cannot be combined with evidence inputs",
                file=sys.stderr,
            )
            return 2
        if not _nonempty_string(args.tlapm_version) or args.tlaps_log_dir is None:
            print(
                "--write-evidence requires --tlapm-version and --tlaps-log-dir",
                file=sys.stderr,
            )
            return 2
        try:
            evidence = build_release_evidence(
                tlapm_version=args.tlapm_version,
                log_dir=args.tlaps_log_dir,
            )
            args.write_evidence.parent.mkdir(parents=True, exist_ok=True)
            args.write_evidence.write_text(
                json.dumps(evidence, indent=2, ensure_ascii=False) + "\n",
                encoding="utf-8",
            )
        except (OSError, UnicodeDecodeError, ValueError) as error:
            print(f"proof evidence generation failed: {error}", file=sys.stderr)
            return 1
        print(f"wrote Sumeragi v2 proof evidence to {args.write_evidence}")
        return 0

    if args.write_cross_tool_evidence is not None:
        if args.evidence is None or args.verus_evidence is None:
            print(
                "--write-cross-tool-evidence requires --evidence and "
                "--verus-evidence",
                file=sys.stderr,
            )
            return 2
        if args.cross_tool_evidence is not None:
            print(
                "--write-cross-tool-evidence cannot be combined with "
                "--cross-tool-evidence",
                file=sys.stderr,
            )
            return 2
        try:
            ledger = load_ledger(args.ledger)
            tlaps_evidence = load_ledger(args.evidence)
            verus_evidence = load_ledger(args.verus_evidence)
            if not all(
                isinstance(value, dict)
                for value in (ledger, tlaps_evidence, verus_evidence)
            ):
                raise ValueError("ledger and component evidence must be JSON objects")
            cross_tool_evidence = build_cross_tool_evidence(
                ledger,
                tlaps_evidence=tlaps_evidence,
                verus_evidence=verus_evidence,
                verus_log_path=args.verus_log,
            )
            args.write_cross_tool_evidence.parent.mkdir(
                parents=True, exist_ok=True
            )
            args.write_cross_tool_evidence.write_text(
                json.dumps(
                    cross_tool_evidence,
                    indent=2,
                    sort_keys=True,
                    ensure_ascii=False,
                )
                + "\n",
                encoding="utf-8",
            )
        except (
            OSError,
            UnicodeDecodeError,
            json.JSONDecodeError,
            DuplicateKeyError,
            ValueError,
        ) as error:
            print(
                f"cross-tool evidence generation failed: {error}",
                file=sys.stderr,
            )
            return 1
        print(
            "wrote Sumeragi v2 cross-tool evidence to "
            f"{args.write_cross_tool_evidence}"
        )
        return 0

    if args.evidence is not None and not args.release:
        print(
            "--evidence is only valid with --release or "
            "--write-cross-tool-evidence",
            file=sys.stderr,
        )
        return 2
    if args.verus_evidence is not None and not args.release:
        print(
            "--verus-evidence is only valid with --release or "
            "--write-cross-tool-evidence",
            file=sys.stderr,
        )
        return 2
    if args.verus_log is not None and not args.release:
        print(
            "--verus-log is only valid with --release or "
            "--write-cross-tool-evidence",
            file=sys.stderr,
        )
        return 2
    if args.verus_log is not None and args.verus_evidence is None:
        print("--verus-log requires --verus-evidence", file=sys.stderr)
        return 2
    if args.cross_tool_evidence is not None and not args.release:
        print("--cross-tool-evidence is only valid with --release", file=sys.stderr)
        return 2
    try:
        ledger = load_ledger(args.ledger)
    except (OSError, json.JSONDecodeError, DuplicateKeyError) as error:
        print(f"proof ledger load failed: {error}", file=sys.stderr)
        return 1
    if not isinstance(ledger, dict):
        print("proof ledger must be a JSON object", file=sys.stderr)
        return 1
    evidence: dict[str, Any] | None = None
    verus_evidence: dict[str, Any] | None = None
    cross_tool_evidence: dict[str, Any] | None = None
    if args.release:
        if args.evidence is None:
            print("release gate requires --evidence", file=sys.stderr)
            return 1
        try:
            evidence = load_ledger(args.evidence)
        except (OSError, json.JSONDecodeError, DuplicateKeyError) as error:
            print(f"proof evidence load failed: {error}", file=sys.stderr)
            return 1
        if not isinstance(evidence, dict):
            print("proof evidence must be a JSON object", file=sys.stderr)
            return 1
        for label, path in (
            ("Verus evidence", args.verus_evidence),
            ("cross-tool evidence", args.cross_tool_evidence),
        ):
            if path is None:
                continue
            try:
                loaded = load_ledger(path)
            except (OSError, json.JSONDecodeError, DuplicateKeyError) as error:
                print(f"{label} load failed: {error}", file=sys.stderr)
                return 1
            if not isinstance(loaded, dict):
                print(f"{label} must be a JSON object", file=sys.stderr)
                return 1
            if label == "Verus evidence":
                verus_evidence = loaded
            else:
                cross_tool_evidence = loaded
    result = validate_ledger(
        ledger,
        release=args.release,
        evidence=evidence,
        verus_evidence=verus_evidence,
        cross_tool_evidence=cross_tool_evidence,
        verus_log_path=args.verus_log,
    )
    if result.errors:
        for error in result.errors:
            print(f"error: {error}", file=sys.stderr)
        return 1
    if args.release:
        status = "release-complete"
    elif result.machine_checked_completion:
        status = "completion-claimed; release evidence not checked"
    else:
        status = "release-incomplete"
    print(f"Sumeragi v2 proof ledger is structurally valid ({status})")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
